function termify(text){const keys=Object.keys(terms).sort((a,b)=>b.length-a.length);if(!keys.length)return text;const matcher=new RegExp(`(^|[^\\p{L}\\p{N}_])(${keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')})(?=$|[^\\p{L}\\p{N}_])`,'giu');return text.replace(matcher,(whole,before,word)=>{const key=keys.find(k=>k.toLowerCase()===word.toLowerCase())||word;return `${before}<button type="button" class="term" data-term="${key}">${word}</button>`})}
