function renderGlossary(){setNav('glossary');$('#crumbCurrent').textContent='Dictionnaire';const entries=Object.entries(terms);content.innerHTML=`<div class="page-header"><span class="eyebrow">LE JARGON, ENFIN EXPLIQUÃ‰</span><h1>Dictionnaire global</h1><p>Chaque terme propose une explication, une analogie, un exemple et un piÃ¨ge frÃ©quent. Cliquez sur une fiche pour lâ€™ouvrir.</p></div><label class="search-box" style="width:100%;max-width:420px;margin-bottom:18px"><span>âŒ•</span><input id="glossarySearch" type="search" placeholder="Filtrer les ${entries.length} termesâ€¦" aria-label="Filtrer le dictionnaire"/><kbd>Aa</kbd></label><div class="glossary-grid">${entries.map(([name,info])=>`<article class="glossary-card" data-term="${name}"><h3>${name}</h3><p>${info[0]}</p><span>Lire la fiche complÃ¨te â†’</span></article>`).join('')}</div><div class="empty-state" id="glossaryEmpty" hidden>Aucun terme ne correspond Ã  votre recherche.</div>`;wireContent();const input=$('#glossarySearch'),cards=[...content.querySelectorAll('.glossary-card')],empty=$('#glossaryEmpty');input.oninput=()=>{const query=input.value.trim().toLocaleLowerCase('fr');let visible=0;for(const card of cards){const show=card.textContent.toLocaleLowerCase('fr').includes(query);card.hidden=!show;if(show)visible++}empty.hidden=visible!==0}}
