function renderSearch(q){searchTerm=q;setNav('');$('#crumbCurrent').textContent='Recherche';const matches=chapters.filter(c=>`${c.id} ${c.title} ${c.lead} ${c.terms.join(' ')} ${c.simple}`.toLowerCase().includes(q.toLowerCase()));const gloss=Object.keys(terms).filter(t=>t.toLowerCase().includes(q.toLowerCase()));content.innerHTML=`<div class="page-header"><span class="eyebrow">RECHERCHE GLOBALE</span><h1>RÃ©sultats pour Â« ${q.replace(/[<>]/g,'')} Â»</h1><p>${matches.length} chapitre${matches.length!==1?'s':''} et ${gloss.length} terme${gloss.length!==1?'s':''} trouvÃ©${gloss.length!==1?'s':''}.</p></div>${matches.length?`<div class="search-results">${matches.map(c=>`<button class="search-result" data-chapter="${c.id}"><small>CHAPITRE ${c.id} Â· ${modules[c.module].title} Â· ${c.time}</small><strong>${c.title}</strong><span>${c.lead}</span></button>`).join('')}</div>`:'<div class="empty-state"><strong>Aucun chapitre trouvÃ©</strong>Essayez un autre mot ou une notion voisine.</div>'}${gloss.length?`<div class="section-heading" style="margin-top:25px"><div><h2>Dans le dictionnaire</h2><p>Ouvrez une fiche pour dÃ©couvrir une dÃ©finition, une analogie et un exemple.</p></div></div><div class="glossary-grid">${gloss.slice(0,12).map(t=>`<article class="glossary-card" data-term="${t}"><h3>${t}</h3><p>${terms[t][0]}</p><span>Lire la fiche complÃ¨te â†’</span></article>`).join('')}</div>`:''}`;wireContent()}
