function runSimulation(diag){clearInterval(diag._interval);const steps=[...diag.querySelectorAll('.diagram-step')];let i=0;diag.querySelector('.sim-status').textContent='Le parcours commenceâ€¦';diag._interval=setInterval(()=>{steps.forEach(s=>s.classList.remove('active'));if(i>=steps.length){clearInterval(diag._interval);diag.querySelector('.sim-status').textContent='Parcours terminÃ©. La rÃ©ponse a atteint sa destination.';return}steps[i].classList.add('active');const c=chapters.find(x=>x.id===diag.dataset.sim);diag.querySelector('.sim-status').textContent=`Ã‰tape ${i+1}/${steps.length} : ${c.diagram[i][0]} â€” ${c.diagram[i][1]}.`;i++},900)}
