function renderAchievements(){setNav('achievements');$('#crumbCurrent').textContent='Badges & certificat';const badges=getBadges(),earned=badges.filter(b=>b.earned).length,allDone=chapters.every(c=>state.completed.includes(c.id)),percent=Math.round(state.completed.length/chapters.length*100);content.innerHTML=`<div class="page-header"><span class="eyebrow">PROGRESSION & RECONNAISSANCE</span><h1>Badges & certificat</h1><p>Les badges marquent des Ã©tapes concrÃ¨tes. Le certificat interne se dÃ©bloque lorsque vous avez validÃ© tous les chapitres du parcours.</p></div><section class="stats-grid"><article class="stat-card"><div class="stat-label">Progression du parcours <i>â—«</i></div><div class="stat-value">${percent}%</div><div class="module-progress" style="width:100%;margin-top:9px"><span style="width:${percent}%"></span></div></article><article class="stat-card"><div class="stat-label">Badges obtenus <i>âœ¦</i></div><div class="stat-value">${earned}<span style="font-size:12px;color:#98a8c1"> / ${badges.length}</span></div><div class="stat-sub">En validant les modules</div></article><article class="stat-card"><div class="stat-label">Niveau <i>â†—</i></div><div class="stat-value">${Math.floor(state.xp/100)+1}</div><div class="stat-sub">${state.xp} XP accumulÃ©s</div></article></section><div class="section-heading"><div><h2>Vos badges</h2><p>Ils se dÃ©bloquent en validant des Ã©tapes du parcours.</p></div></div><div class="quick-links badge-grid">${badges.map(b=>`<article class="quick-card badge-card ${b.earned?'earned':''}"><span class="quick-icon">${b.icon}</span><span><strong>${b.name}</strong><small>${b.detail}</small><small class="badge-status">${b.earned?'Obtenu âœ“':'Ã€ dÃ©bloquer'}</small></span></article>`).join('')}</div><section class="certificate-card ${allDone?'earned':''}"><div><span class="eyebrow">CERTIFICATION INTERNE Â· SENIOR VIBE CODING ACADEMY</span><h2>${allDone?'Parcours validÃ©':'Certificat de fin de parcours'}</h2><p>${allDone?'Vous avez validÃ© les 96 chapitres. Votre certificat interne est prÃªt.':'Validez les 96 chapitres pour obtenir le certificat interne.'}</p></div><div class="certificate-progress"><strong>${state.completed.length} / ${chapters.length}</strong><small>chapitres validÃ©s</small><div class="module-progress"><span style="width:${percent}%"></span></div></div>${allDone?`<button class="button primary" id="printCertificate">Imprimer le certificat <span>â†—</span></button>`:''}</section>`;wireContent();const print=$('#printCertificate');if(print)print.onclick=()=>window.print()}

const renderLessonBase=renderLesson;
renderLesson=function(c){state.history=(state.history||[]).filter(x=>x.id!==c.id);state.history.unshift({id:c.id,at:new Date().toISOString()});state.history=state.history.slice(0,100);storage.set(STORAGE,JSON.stringify(state));renderLessonBase(c);const main=content.querySelector('.lesson-main'),first=main?.querySelector('.learn-section');if(!main||!first)return;const intro=document.createElement('section');intro.className='learn-section';intro.id='introduction';intro.innerHTML=`<h2>Introduction</h2><p>${termify(c.lead)}</p>`;first.before(intro);const problemParagraph=first.querySelector('p');if(problemParagraph){const problem=document.createElement('section');problem.className='learn-section';problem.id='probleme-a-resoudre';problem.innerHTML=`<h2>Le problÃ¨me Ã  rÃ©soudre</h2>${problemParagraph.outerHTML}`;problemParagraph.remove();first.after(problem)}const practice=main.querySelector(`#${sectionId('Ã€ vous de jouer')}`);if(practice){const simulation=practice.querySelector('.analogy');if(simulation){const guided=document.createElement('section');guided.className='learn-section';guided.id='simulation-guidee';guided.innerHTML=`<h2>Simulation guidÃ©e</h2>${simulation.outerHTML}`;simulation.remove();practice.after(guided)}}const flash=main.querySelector(`#${sectionId('Flashcards')}`);if(flash){const review=document.createElement('section');review.className='learn-section';review.id='revision';review.innerHTML='<h2>RÃ©vision espacÃ©e</h2><p>Refaites ces cartes demain, puis dans trois jours et une semaine. Essayez de rÃ©pondre avant de retourner chaque carte et revenez Ã  lâ€™explication si un terme reste flou.</p><div class="revision-steps"><span>Demain Â· rappel court</span><span>Dans 3 jours Â· relier les idÃ©es</span><span>Dans 7 jours Â· expliquer sans aide</span></div>';flash.after(review)}const complete=main.querySelector('.complete-panel');if(complete){const label=document.createElement('span');label.className='eyebrow';label.textContent='VALIDATION DES ACQUIS';complete.querySelector(':scope > div')?.prepend(label)}};

const renderHomeCompletionBase=renderHome;
renderHome=function(){renderHomeCompletionBase();if(state.completed.length<chapters.length)return;const primary=content.querySelector('.hero-copy [data-chapter]');if(primary){primary.removeAttribute('data-chapter');primary.dataset.view='achievements';primary.innerHTML='Voir mon certificat <span>â†’</span>'}const card=content.querySelector('.continue-card');if(card){card.querySelector('.eyebrow').textContent='PARCOURS TERMINÃ‰';card.querySelector('h3').textContent='FÃ©licitations !';card.querySelector('p').textContent='Vous avez validÃ© les 96 chapitres. Consultez vos badges et votre certificat interne.';const button=card.querySelector('[data-chapter]');button.removeAttribute('data-chapter');button.dataset.view='achievements';button.innerHTML='Voir mes acquis <span>â†’</span>'}wireContent()};

const wireContentBase=wireContent;
wireContent=function(){wireContentBase();content.querySelectorAll('[data-quiz]').forEach(q=>{const c=chapters.find(x=>x.id===q.dataset.quiz);if(!c)return;const feedback=q.querySelector('.quiz-feedback');let stage=0;let firstCorrect=false;const options=[...q.querySelectorAll('.quiz-option')];options.forEach(opt=>opt.onclick=()=>{if(stage!==0)return;firstCorrect=+opt.dataset.answer===c.quiz.answer;opt.classList.add(firstCorrect?'correct':'wrong');if(!firstCorrect)q.querySelector(`[data-answer="${c.quiz.answer}"]`)?.classList.add('correct');q.dataset.answered='yes';const stat=state.quizStats[c.id]||{right:0,wrong:0};stat[firstCorrect?'right':'wrong']++;state.quizStats[c.id]=stat;storage.set(STORAGE,JSON.stringify(state));feedback.textContent=(firstCorrect?'Bonne rÃ©ponse. ':'Pas tout Ã  fait. ')+c.quiz.explain;const follow=document.createElement('div');follow.className='adaptive-followup';const right=firstCorrect?c.advanced:c.analogy;const distractor=firstCorrect?c.simple:c.problem;follow.innerHTML=`<div class="adaptive-head"><span class="eyebrow">${firstCorrect?'DÃ‰FI APPROFONDI':'RAPPEL GUIDÃ‰'} Â· Ã‰TAPE 2/2</span><h3>${firstCorrect?'Ã€ prÃ©sent, quel principe faut-il garder en tÃªte ?':'Quelle idÃ©e vous aide Ã  reconnaÃ®tre ce concept ?'}</h3></div><button class="quiz-option" data-follow="right">${right}</button><button class="quiz-option" data-follow="wrong">${distractor}</button><div class="quiz-feedback"></div>`;q.append(follow);stage=1;follow.querySelectorAll('[data-follow]').forEach(answer=>answer.onclick=()=>{if(stage!==1)return;stage=2;const correctAnswer=answer.dataset.follow==='right';answer.classList.add(correctAnswer?'correct':'wrong');if(!correctAnswer)follow.querySelector('[data-follow="right"]').classList.add('correct');const second=state.quizStats[c.id];second[correctAnswer?'right':'wrong']++;storage.set(STORAGE,JSON.stringify(state));follow.querySelector('.quiz-feedback').textContent=correctAnswer?'Bien vu. Vous reliez maintenant la notion Ã  son application.':'Relisez lâ€™explication puis rÃ©essayez dans une prochaine rÃ©vision.';q.dataset.answered='complete';if(firstCorrect&&correctAnswer&&!state.quizBonus?.includes(c.id)){state.quizBonus||=[];state.quizBonus.push(c.id);state.xp+=5;save();toast('Quiz maÃ®trisÃ© Â· +5 XP')}else updateStats()})})})};

const wireAdaptiveOrderBase=wireContent;
wireContent=function(){wireAdaptiveOrderBase();content.querySelectorAll('[data-quiz]').forEach(q=>{const c=chapters.find(x=>x.id===q.dataset.quiz);if(!c)return;const chapterNumber=Number.isInteger(Number(c.id))?Number(c.id):Number(c.id.split('.').pop());q.querySelectorAll('.quiz-option[data-answer]').forEach(option=>{const previous=option.onclick;option.onclick=function(event){previous.call(this,event);const follow=q.querySelector('.adaptive-followup');if(follow&&chapterNumber%2===0)follow.append(follow.querySelector('[data-follow="right"]'))}})})};

function saveAcademyRoute(route){const hash='#'+route,previous=location.hash.slice(1)||'home';state.lastRoute=route;state.lastScrollY=0;storage.set(STORAGE,JSON.stringify(state));if(location.hash===hash)return false;try{history.replaceState({...history.state,academyRoute:previous,academyScrollY:window.scrollY},'',location.href);history.pushState({academyRoute:route,academyScrollY:0},'',hash);return true}catch{ignoreAcademyHash=true;location.hash=route;return true}}
let ignoreAcademyHash=false;
function withAcademyRoute(fn,getRoute){return function(...args){const result=fn.apply(this,args),route=getRoute(...args),changed=saveAcademyRoute(route);if(changed)window.scrollTo(0,0);return result}}
renderHome=withAcademyRoute(renderHome,()=> 'home');showModule=withAcademyRoute(showModule,id=>'module/'+id);renderLesson=withAcademyRoute(renderLesson,c=>'lesson/'+encodeURIComponent(c.id));renderPath=withAcademyRoute(renderPath,()=> 'path');renderMindmap=withAcademyRoute(renderMindmap,()=> 'mindmap');renderGlossary=withAcademyRoute(renderGlossary,()=> 'glossary');renderSaved=withAcademyRoute(renderSaved,()=> 'saved');renderHistory=withAcademyRoute(renderHistory,()=> 'history');renderAchievements=withAcademyRoute(renderAchievements,()=> 'achievements');renderSearch=withAcademyRoute(renderSearch,q=>{state.searchTerm=q;return 'search'});
function renderAcademyRoute(route){const [view,...parts]=route.split('/');if(view==='lesson'){let id;try{id=decodeURIComponent(parts.join('/'))}catch{}const chapter=chapters.find(c=>c.id===id);return chapter?renderLesson(chapter):renderHome()}if(view==='module'){const id=Number(parts[0]);return modules.some(m=>m.id===id)?showModule(id):renderHome()}if(view==='search'){const q=state.searchTerm||'';$('#searchInput').value=q;return q?renderSearch(q):renderHome()}if(['home','path','mindmap','glossary','saved','history','achievements'].includes(view))return navigate(view);return renderHome()}
function restoreAcademyRoute(){const route=location.hash.slice(1)||state.lastRoute||'home';state.lastRoute=route;storage.set(STORAGE,JSON.stringify(state));renderAcademyRoute(route);const savedY=history.state?.academyRoute===route?history.state.academyScrollY:state.lastScrollY||0;requestAnimationFrame(()=>window.scrollTo(0,Number(savedY)||0))}
window.addEventListener('pagehide',()=>{state.lastRoute=location.hash.slice(1)||state.lastRoute||'home';state.lastScrollY=window.scrollY;storage.set(STORAGE,JSON.stringify(state));try{history.replaceState({...history.state,academyRoute:state.lastRoute,academyScrollY:window.scrollY},'',location.href)}catch{}});
window.addEventListener('popstate',event=>{const route=location.hash.slice(1)||event.state?.academyRoute||'home';state.lastRoute=route;storage.set(STORAGE,JSON.stringify(state));renderAcademyRoute(route);requestAnimationFrame(()=>window.scrollTo(0,Number(event.state?.academyScrollY)||0))});
window.addEventListener('hashchange',()=>{if(ignoreAcademyHash){ignoreAcademyHash=false;return}const route=location.hash.slice(1)||'home';state.lastRoute=route;storage.set(STORAGE,JSON.stringify(state));renderAcademyRoute(route)});
buildModuleNav();updateStats();restoreAcademyRoute();
